'use strict';
if(process.env.EXPLICATIONS_CREATION_ASSET_DIR)process.env.TITRES_CREATION_ASSET_DIR=process.env.EXPLICATIONS_CREATION_ASSET_DIR;
const {test}=require('node:test'),assert=require('node:assert/strict'),{execFileSync}=require('node:child_process'),{chromium}=require('playwright'),{setup,begin,finish,selected,langs,read}=require('./fixtures/creation-i18n-navigateur.cjs'),base='d6644047eb7ed130e76f9069b8b91cf7a99d291d',old=execFileSync('git',['show',base+':creation.js'],{cwd:require('node:path').resolve(__dirname,'../..'),encoding:'utf8',maxBuffer:4e6});
async function semantic(page){return page.evaluate(()=>{const z=document.getElementById('creation-erreur');return {text:z.textContent,tags:Array.from(z.querySelectorAll('*')).map(n=>n.tagName).filter(t=>t!=='SPAN'),em:z.querySelector('em')?.textContent||null};});}
async function check(page,lang){await page.evaluate(async lang=>{await i18next.changeLanguage(lang);appliquerTraductionsRP();},lang);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await page.evaluate(()=>{const z=document.getElementById('creation-erreur');return z.scrollWidth>z.clientWidth;}),false);for(const span of await page.locator('#creation-erreur span[data-i18n]').all()){const key=await span.getAttribute('data-i18n'),raw=await span.getAttribute('data-i18n-values'),values=raw?JSON.parse(raw):undefined;assert.equal(await span.textContent(),await page.evaluate(({key,values})=>i18next.t(key,{values,replace:{...values,values}}),{key,values}));assert.equal(await span.getAttribute('dir'),lang==='ar'?'rtl':null);}}
test('explications : six messages entiers en neuf langues, 320/390/1280, français/appels identiques à main et 270 bascules sans dépense ni requête',async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let switches=0;
 try{for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:900}}),before=await browser.newPage({viewport:{width,height:900}}),errors=[],requests=[];page.on('pageerror',e=>errors.push(String(e)));page.on('request',r=>requests.push(r.url()));await setup(page,false);await page.addScriptTag({content:selected(read('creation.js'),['rpAnnoterCorpsErreurCreation'])});await setup(before,true,old);
 for(const mode of ['nom_deja_pris','compte_a_deja_un_personnage','genre_requis','session_perimee','raison_libre','otherOwned','throw']){
  for(const p of [page,before])await p.evaluate(async()=>{await i18next.changeLanguage('fr');appliquerTraductionsRP();});assert.deepEqual(await begin(page,mode),await begin(before,mode));const done=await finish(page),previous=await finish(before);assert.equal(done.business,previous.business,'mêmes appels, cache, verrou et navigation que main');assert.deepEqual(await semantic(page),await semantic(before),'français entier, paragraphes et emphase identiques');assert.ok(await page.locator('#creation-erreur span[data-i18n]').count()>=1);
  const business=done.business,ui=await page.evaluate(()=>uiSnapshot());for(const lang of langs){await check(page,lang);assert.equal(await page.evaluate(()=>businessSnapshot()),business);assert.equal(await page.evaluate(()=>uiSnapshot()),ui);switches++;}
 }
 // Des noms et motifs ressemblant à des balises ou à un libellé du jeu restent des valeurs opaques.
 for(const [mode,name]of [['nom_deja_pris','名 <img src=x> & اسم'],['nom_deja_pris','Creation impossible'],['motif <b>原 & اسم</b>','PJ Fixture']]){await page.evaluate(name=>G.name=name,name);await begin(page,mode);await finish(page);const business=await page.evaluate(()=>businessSnapshot()),value=mode==='nom_deja_pris'?name:mode;for(const lang of langs){await check(page,lang);assert.ok((await page.locator('#creation-erreur').textContent()).includes(value));assert.equal(await page.locator('#creation-erreur img,#creation-erreur b').count(),0);assert.equal(await page.evaluate(()=>businessSnapshot()),business);switches++;}}
 await page.evaluate(()=>{G.name='PJ Fixture';delete i18next.getResourceBundle('de','translation').connectionUi.characterCreationGenericBody;});await begin(page,'raison_libre');await finish(page);await check(page,'de');assert.equal(await page.locator('#creation-erreur span[data-i18n]').textContent(),"Votre personnage n'a pas pu etre enregistre (raison_libre). Verifiez votre connexion et reessayez ; rien n'a ete perdu.");
 // Sans ressource française, le rendu original complet sert de repli, sans clé visible.
 await page.evaluate(()=>{delete i18next.getResourceBundle('fr','translation').connectionUi.characterCreationGenericBody;});await begin(page,'raison_libre');await finish(page);assert.equal(await page.locator('#creation-erreur span[data-i18n]').count(),0);assert.ok((await page.locator('#creation-erreur').textContent()).includes("Votre personnage n'a pas pu etre enregistre (raison_libre)."));
 await page.evaluate(()=>{window.i18next=undefined;window.appliquerTraductionsRP=undefined;});await begin(page,'genre_requis',true);await finish(page);assert.equal(await page.locator('#creation-erreur').textContent(),"Genre manquantLe genre de votre personnage est obligatoire. Revenez a l'etape de l'identite pour le choisir, puis validez de nouveau.Rien n'a ete perdu.");assert.deepEqual(errors,[]);assert.deepEqual(requests,[]);await page.close();await before.close();}
 assert.equal(switches,270);
 }finally{await browser.close();}
});
